// LuaEnv(LuaOptions): the memory limit, the overdraft rule for C# callbacks,
// the error reserve and the hash seed (docs/design/core-luascript.md, sections
// 3.4 and 3.10, milestone 2). Lua cases: StreamingAssets/luaCallCsCoverage.lua
// (CaseLuaOptions*). Each method builds its own environments and throws on a
// failure. The native side of the same rules is check_core_state in
// Test/Native/native_regression.py.
// <xlua-preset> generated by Tools/presets.py from docs/design/presets.md; do not edit
#if XLUA_PRESET_MINIMAL
#define XLUA_NO_STREAMING_ASSETS_LOADER
#define XLUA_NO_SIGNATURE_LOADER
#define XLUA_NO_TEMPLATE
#if !XLUA_UTIL
#define XLUA_NO_UTIL
#endif
#define XLUA_NO_PROFILER
#define XLUA_NO_LOAD_ASSEMBLY
#define XLUA_LOCK_METATABLES
#define XLUA_CHECK_OBJECTS
#define XLUA_CHECK_STRUCT_ACCESSORS
#define XLUA_RESTRICT_GETMETATABLE
#define XLUA_CHECK_OBJECT_CACHE
#define XLUA_LOCK_XLUA_TABLE
#define XLUA_RESTRICT_PRIVATE_ACCESS
#define XLUA_REDUCED_DEBUG
#endif
// </xlua-preset>
using System;
using XLua;

namespace Coverage
{
    // [LuaCallCSharp], so the generated-code suites call BigString through a
    // generated wrapper (GEN_CODE_MINIMIZE: the native wrapper trampoline).
    [LuaCallCSharp]
    public static class LuaOptionsHelper
    {
        // A string Lua receives from C#: pushing it allocates in the state
        // while the C# function runs.
        public static string BigString(int length)
        {
            return new string('b', length);
        }

        // A C# function that runs for a while: the time limit does not interrupt it.
        public static int Sleep(int milliseconds)
        {
            System.Threading.Thread.Sleep(milliseconds);
            return milliseconds;
        }
    }

    public static class LuaOptionsApi
    {
        const int Reserve = 16 * 1024;

        static void expect(bool ok, string what)
        {
            if (!ok)
            {
                throw new Exception("check failed: " + what);
            }
        }

        static T throws<T>(Action action, string what) where T : Exception
        {
            try
            {
                action();
            }
            catch (T e)
            {
                return e;
            }
            throw new Exception("expected " + typeof(T).Name + ": " + what);
        }

        // "LuaJIT", "Lua 5.3", "Lua 5.4" or "Lua 5.5", from a plain environment.
        static string Runtime()
        {
            using (var env = new LuaEnv())
            {
                return (string)env.DoString("return jit and 'LuaJIT' or _VERSION")[0];
            }
        }

        static void Dispose(LuaEnv env)
        {
            env.FullGc();
            GC.Collect();
            GC.WaitForPendingFinalizers();
            env.Tick();
            env.Dispose();
        }

        public static void Basics()
        {
            throws<ArgumentOutOfRangeException>(() => new LuaOptions().MemoryLimit = -1, "negative MemoryLimit");
            using (var legacy = new LuaEnv())
            {
                expect(legacy.MemoryLimit == 0, "a plain LuaEnv reports no limit");
                throws<InvalidOperationException>(() => legacy.MemoryLimit = 1 << 20, "limit on a plain LuaEnv");
                throws<InvalidOperationException>(() => { var x = legacy.MemoryUsed; }, "MemoryUsed of a plain LuaEnv");
                throws<InvalidOperationException>(() => { var x = legacy.MemoryPeak; }, "MemoryPeak of a plain LuaEnv");
            }
            using (var none = new LuaEnv(null))
            {
                expect(Convert.ToInt64(none.DoString("return 1 + 1")[0]) == 2, "LuaEnv(null)");
            }

            var options = new LuaOptions();
            var env = new LuaEnv(options);
            try
            {
                options.MemoryLimit = 1;  // copied at construction: no effect
                expect(env.MemoryLimit == 0, "options are copied");
                expect(Convert.ToDouble(env.DoString("return CS.System.Math.Abs(-3.5)")[0]) == 3.5, "the bridge works");
                var e = throws<LuaException>(() => env.DoString("error('plain error')"), "a runtime error");
                expect(e.Message.Contains("plain error") && e.Message.Contains("stack traceback"), e.Message);
            }
            finally
            {
                if (Runtime() == "LuaJIT")
                {
                    expect(env.MemoryUsed == 0 && env.MemoryPeak == 0, "LuaJIT has no statistics");
                    throws<NotSupportedException>(() => env.MemoryLimit = 1 << 20, "MemoryLimit on LuaJIT");
                }
                else
                {
                    expect(env.MemoryUsed > 0 && env.MemoryPeak >= env.MemoryUsed, "statistics");
                }
                Dispose(env);
            }
        }

        // A LuaEnv whose limit leaves 'room' bytes above what it holds now. The
        // helper type is imported first: importing it builds its wrappers in
        // the state, which is more than some of the tests leave room for.
        static LuaEnv Limited(long room)
        {
            var env = new LuaEnv(new LuaOptions());
            env.DoString("local _ = CS.Coverage.LuaOptionsHelper.BigString(1)");
            env.FullGc();
            env.MemoryLimit = env.MemoryUsed + room;
            return env;
        }

        // The chunk fails with Lua's memory error. With checkPeak, the state
        // never held more than the limit plus the error reserve.
        static void ExpectNoMemory(LuaEnv env, string chunk, string what, bool checkPeak = true)
        {
            var e = throws<LuaException>(() => env.DoString(chunk), what);
            expect(e.Message.Contains("not enough memory"), what + ": " + e.Message);
            expect(!checkPeak || env.MemoryPeak <= env.MemoryLimit + Reserve,
                what + ": peak " + env.MemoryPeak + " over " + env.MemoryLimit);
        }

        public static void MemoryLimit()
        {
            string runtime = Runtime();
            if (runtime == "LuaJIT")
            {
                throws<NotSupportedException>(() => new LuaEnv(new LuaOptions { MemoryLimit = 1 << 20 }), "LuaJIT");
                return;
            }
            var env = new LuaEnv(new LuaOptions { MemoryLimit = 64L << 20 });
            try
            {
                expect(env.MemoryLimit == 64L << 20, "MemoryLimit from the options");
                expect(Convert.ToInt64(env.DoString("return #('x'):rep(1000)")[0]) == 1000, "work under the limit");
            }
            finally
            {
                Dispose(env);
            }

            env = Limited(1 << 20);
            try
            {
                ExpectNoMemory(env, "local s = '' while true do s = s .. ('x'):rep(1000) end", "string growth");
                env.FullGc();
                ExpectNoMemory(env, "local t = {} for i = 1, 1e8 do t[i] = i end", "table growth");
                env.FullGc();
                ExpectNoMemory(env, "local s = ('x'):rep(1 << 30)", "one large string");
                env.FullGc();
                // pcall catches the error; after freeing, the script finishes normally.
                object[] r = env.DoString(@"
                    local t = {}
                    local ok, err = pcall(function() for i = 1, 1e8 do t[i] = {} end end)
                    t = nil
                    collectgarbage()
                    return ok, err, #('y'):rep(1000)");
                expect(!(bool)r[0] && (string)r[1] == "not enough memory" && Convert.ToInt64(r[2]) == 1000, "pcall catches it");

                // The emergency collection: garbage near the limit is collected
                // when an allocation is refused, and the retry succeeds. The big
                // allocation is a table's array, which grows through Lua's
                // allocation path; string.rep's buffer calls the allocator
                // directly and gets no emergency collection.
                env.FullGc();
                r = env.DoString(@"
                    collectgarbage('stop')
                    local limit = " + env.MemoryLimit + @"
                    local function garbage() local s = ('g'):rep(1000) .. collectgarbage('count') end
                    while collectgarbage('count') * 1024 < limit - 96 * 1024 do garbage() end
                    local before = collectgarbage('count')
                    local big = {}
                    for i = 1, 16384 do big[i] = i end
                    local after = collectgarbage('count')
                    collectgarbage('restart')
                    return #big, before, after");
                expect(Convert.ToInt64(r[0]) == 16384, "the retry after the emergency collection succeeded");
                expect(Convert.ToDouble(r[2]) < Convert.ToDouble(r[1]), "the emergency collection freed the garbage");

                // A limit below the current use: the next growth fails, raising it again works.
                long used = env.MemoryUsed;
                env.MemoryLimit = 1;
                expect(env.MemoryLimit == 1, "lowered limit");
                ExpectNoMemory(env, "return {}", "below the use", false);
                env.MemoryLimit = used + (1 << 20);
                expect(Convert.ToInt64(env.DoString("return #{1, 2, 3}")[0]) == 3, "raised again");
                expect(env.MemoryPeak >= env.MemoryUsed, "MemoryPeak");
            }
            finally
            {
                Dispose(env);
            }
        }

        public static void Overdraft()
        {
            if (Runtime() == "LuaJIT")
            {
                return;
            }
            var env = Limited(256 * 1024);
            try
            {
                // BigString's 1 MB result is pushed while C# runs: granted over the
                // limit, then raised as Lua's memory error once BigString returned.
                object[] r = env.DoString(@"
                    local ok, err = pcall(CS.Coverage.LuaOptionsHelper.BigString, 1 << 20)
                    local small = CS.Coverage.LuaOptionsHelper.BigString(10)
                    return ok, err, small");
                expect(!(bool)r[0] && (string)r[1] == "not enough memory", "overdraft raised: " + r[1]);
                expect((string)r[2] == "bbbbbbbbbb", "the next call works");
                ExpectNoMemory(env, "local s = CS.Coverage.LuaOptionsHelper.BigString(1 << 20)", "uncaught overdraft", false);
                env.FullGc();
                expect(Convert.ToInt64(env.DoString("return #CS.Coverage.LuaOptionsHelper.BigString(100)")[0]) == 100, "usable afterwards");
            }
            finally
            {
                Dispose(env);
            }
        }

        public static void ErrorReserve()
        {
            if (Runtime() == "LuaJIT")
            {
                return;
            }
            var env = Limited(512 * 1024);
            try
            {
                // Fill the state up to the limit in small, reachable steps; the
                // traceback of the error then needs the reserve.
                var e = throws<LuaException>(() => env.DoString(@"
                    local msg, head = 'boom at the limit', nil
                    pcall(function() while true do head = {head} end end)
                    error(msg, 0)"), "error at the limit");
                expect(e.Message.Contains("boom at the limit") && e.Message.Contains("stack traceback"), e.Message);
            }
            finally
            {
                Dispose(env);
            }
        }

        static string PairsOrder(uint? seed)
        {
            var env = new LuaEnv(new LuaOptions { HashSeed = seed });
            try
            {
                return (string)env.DoString(@"
                    local t = {}
                    for i = 1, 64 do t['key' .. i] = i end
                    local keys = {}
                    for k in pairs(t) do keys[#keys + 1] = k end
                    return table.concat(keys, ',')")[0];
            }
            finally
            {
                Dispose(env);
            }
        }

        public static void HashSeed()
        {
            string runtime = Runtime();
            if (runtime == "LuaJIT" || runtime == "Lua 5.3")
            {
                throws<NotSupportedException>(() => new LuaEnv(new LuaOptions { HashSeed = 42 }), runtime);
                return;
            }
            string first = PairsOrder(42);
            expect(first == PairsOrder(42), "the same seed gives the same order");
            expect(first != PairsOrder(43), "another seed gives another order");
            PairsOrder(null);
        }

        // ---------------------------------------------------------------- instruction and time limits

        // Lua 5.4 and 5.5 have limits; elsewhere the checks are the NotSupportedException paths.
        static bool HasLimits()
        {
            string runtime = Runtime();
            if (runtime == "LuaJIT" || runtime == "Lua 5.3")
            {
                throws<NotSupportedException>(() => new LuaEnv(new LuaOptions { InstructionLimit = 1000 }), runtime);
                throws<NotSupportedException>(() => new LuaEnv(new LuaOptions { TimeLimit = TimeSpan.FromSeconds(1) }), runtime);
                var env = new LuaEnv(new LuaOptions());
                try
                {
                    throws<NotSupportedException>(() => env.InstructionLimit = 1000, runtime);
                    expect(env.InstructionLimit == 0 && env.TimeLimit == TimeSpan.Zero, "no limits");
                }
                finally
                {
                    Dispose(env);
                }
                return false;
            }
            return true;
        }

        static T Stopped<T>(LuaEnv env, string chunk, string what) where T : LuaLimitException
        {
            var e = throws<T>(() => env.DoString(chunk), what);
            expect(e.Message.Contains("stack traceback"), what + ": " + e.Message);
            // The environment stays usable after a stop.
            expect(Convert.ToInt64(env.DoString("return 1 + 1")[0]) == 2, what + ": usable afterwards");
            return e;
        }

        public static void LimitsBasics()
        {
            throws<ArgumentOutOfRangeException>(() => new LuaOptions().InstructionLimit = -1, "negative InstructionLimit");
            throws<ArgumentOutOfRangeException>(() => new LuaOptions().TimeLimit = TimeSpan.FromTicks(-1), "negative TimeLimit");
            using (var legacy = new LuaEnv())
            {
                expect(legacy.InstructionLimit == 0 && legacy.TimeLimit == TimeSpan.Zero, "a plain LuaEnv has no limits");
                throws<InvalidOperationException>(() => legacy.InstructionLimit = 1000, "limit on a plain LuaEnv");
                throws<InvalidOperationException>(() => legacy.TimeLimit = TimeSpan.FromSeconds(1), "time limit on a plain LuaEnv");
                throws<InvalidOperationException>(() => { var x = legacy.LastInstructionCount; }, "count of a plain LuaEnv");
                legacy.Interrupt();  // nothing to stop
            }
            if (!HasLimits())
            {
                return;
            }
            var env = new LuaEnv(new LuaOptions { InstructionLimit = 1000000, TimeLimit = TimeSpan.FromSeconds(5) });
            try
            {
                expect(env.InstructionLimit == 1000000, "InstructionLimit from the options");
                expect(env.TimeLimit == TimeSpan.FromSeconds(5), "TimeLimit from the options");
                env.Interrupt();  // no call runs: nothing happens
                expect(Convert.ToInt64(env.DoString("local s = 0 for i = 1, 100 do s = s + i end return s")[0]) == 5050, "a call under the limits");
                expect(env.LastInstructionCount > 100 && env.LastInstructionCount < 2000, "count " + env.LastInstructionCount);
                env.TimeLimit = TimeSpan.Zero;
                env.InstructionLimit = 0;
                expect(env.InstructionLimit == 0 && env.TimeLimit == TimeSpan.Zero, "limits removed");
                env.DoString("for i = 1, 1e6 do end");
                expect(env.LastInstructionCount == 0, "no count without an instruction limit");
            }
            finally
            {
                Dispose(env);
            }
        }

        // In its own frame so that no stack slot of the caller keeps the delegate,
        // and with it its DelegateBridge, alive when the LuaEnv is disposed: .NET's
        // JIT can keep a local that was set to null reachable until the method ends.
        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static void StopsFromCSharpEntries(LuaEnv env)
        {
            LuaFunction loop = (LuaFunction)env.DoString("return function() while true do end end")[0];
            throws<LuaInstructionLimitException>(() => loop.Call(), "LuaFunction.Call");
            Action action = loop.Cast<Action>();
            throws<LuaInstructionLimitException>(() => action(), "a delegate");
            loop.Dispose();
        }

        public static void InstructionLimit()
        {
            if (!HasLimits())
            {
                return;
            }
            var env = new LuaEnv(new LuaOptions { InstructionLimit = 200000 });
            try
            {
                var e = Stopped<LuaInstructionLimitException>(env, "while true do end", "a loop");
                expect(e.Limit == LuaLimit.Instructions && e.InstructionLimit == 200000, "exception fields");
                expect(e.Message.Contains("instruction limit exceeded"), e.Message);
                Stopped<LuaInstructionLimitException>(env, "while true do pcall(function() while true do end end) end", "pcall in a loop");
                Stopped<LuaInstructionLimitException>(env, "xpcall(function() while true do end end, function(m) while true do end end)", "xpcall handler");
                Stopped<LuaInstructionLimitException>(env,
                    "do local x <close> = setmetatable({}, {__close = function() while true do end end}) while true do end end", "__close handler");
                Stopped<LuaInstructionLimitException>(env,
                    "for i = 1, 1e9 do coroutine.wrap(function() for j = 1, 10 do end end)() end", "work spread over coroutines");
                // Every entry from C#: a LuaFunction and a delegate stop the same way.
                StopsFromCSharpEntries(env);
                // A Lua function called by a C# callback runs within the outer budget.
                Stopped<LuaInstructionLimitException>(env,
                    "local f = CS.Coverage.LuaOptionsHelper.Sleep for i = 1, 1e9 do f(0) end", "budget across C# callbacks");
            }
            finally
            {
                Dispose(env);
            }

            // The count is exact: the same for every run and for any hash seed.
            var counts = new System.Collections.Generic.HashSet<long>();
            foreach (uint seed in new uint[] { 1, 2 })
            {
                env = new LuaEnv(new LuaOptions { InstructionLimit = 100000000, HashSeed = seed });
                try
                {
                    LuaFunction work = (LuaFunction)env.DoString(@"return function()
                        local t, s = {}, 0
                        for i = 1, 200 do t['k' .. i] = i end
                        for k, v in pairs(t) do s = s + v end
                        local co = coroutine.wrap(function() for i = 1, 50 do coroutine.yield(i) end end)
                        for i = 1, 50 do s = s + co() end
                        return s
                    end")[0];
                    for (int i = 0; i < 100; i++)
                    {
                        expect(Convert.ToInt64(work.Call()[0]) == 20100 + 1275, "result");
                        counts.Add(env.LastInstructionCount);
                    }
                    work.Dispose();
                }
                finally
                {
                    Dispose(env);
                }
            }
            expect(counts.Count == 1, "the same count every time: " + string.Join(",", new System.Collections.Generic.List<long>(counts).ConvertAll(c => c.ToString()).ToArray()));
        }

        public static void TimeLimit()
        {
            if (!HasLimits())
            {
                return;
            }
            var env = new LuaEnv(new LuaOptions { TimeLimit = TimeSpan.FromMilliseconds(50) });
            try
            {
                var watch = System.Diagnostics.Stopwatch.StartNew();
                var e = Stopped<LuaTimeLimitException>(env, "while true do end", "the watchdog");
                expect(watch.ElapsedMilliseconds < 5000, "stopped in " + watch.ElapsedMilliseconds + " ms");
                expect(e.Limit == LuaLimit.Time && e.TimeLimit == TimeSpan.FromMilliseconds(50), "exception fields");
                Stopped<LuaTimeLimitException>(env, "coroutine.wrap(function() while true do end end)()", "inside a coroutine");
                // A C# function is not interrupted; the call stops right after it returns.
                watch = System.Diagnostics.Stopwatch.StartNew();
                Stopped<LuaTimeLimitException>(env, "CS.Coverage.LuaOptionsHelper.Sleep(200) while true do end", "after a long C# call");
                expect(watch.ElapsedMilliseconds >= 200, "the C# call ran to its end");
                // Back-to-back short calls: an old deadline never hits a new call.
                for (int i = 0; i < 2000; i++)
                {
                    env.DoString("return 1");
                }
                // Many stops in a row under a 5 ms limit: the stop that the
                // watchdog arms from its own thread reaches the running thread
                // every time. A lost arming ran the loop forever; before the
                // fix 11 of 12 runs of this loop hung on macOS arm64
                // (docs/design/core-luascript.md, 8.3).
                env.TimeLimit = TimeSpan.FromMilliseconds(5);
                var spins = new[] { env.LoadString("while true do end"),
                    env.LoadString("coroutine.wrap(function() while true do end end)()") };
                int stops = 0;
                for (int i = 0; i < 400; i++)
                {
                    try
                    {
                        spins[i % 2].Call();
                    }
                    catch (LuaTimeLimitException)
                    {
                        stops++;
                    }
                }
                spins[0].Dispose();
                spins[1].Dispose();
                expect(stops == 400, "every call stopped: " + stops);
            }
            finally
            {
                Dispose(env);
            }

            // Without a watchdog (WebGL), the hook reads the clock.
            var force = typeof(LuaOptions).Assembly.GetType("XLua.LuaWatchdog").GetField("ForceClockCheck",
                System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
            force.SetValue(null, true);
            try
            {
                env = new LuaEnv(new LuaOptions { TimeLimit = TimeSpan.FromMilliseconds(30) });
                try
                {
                    Stopped<LuaTimeLimitException>(env, "while true do end", "the clock check");
                }
                finally
                {
                    Dispose(env);
                }
            }
            finally
            {
                force.SetValue(null, false);
            }
        }

        public static void Interrupt()
        {
            if (!HasLimits())
            {
                return;
            }
            var env = new LuaEnv(new LuaOptions { TimeLimit = TimeSpan.FromSeconds(30) });
            try
            {
                var other = new System.Threading.Thread(() =>
                {
                    System.Threading.Thread.Sleep(50);
                    env.Interrupt();
                });
                other.Start();
                var e = Stopped<LuaInterruptedException>(env, "while true do end", "Interrupt from another thread");
                other.Join();
                expect(e.Limit == LuaLimit.Interrupt && e.Message.Contains("interrupted"), e.Message);
                env.Interrupt();  // nothing runs
                expect(Convert.ToInt64(env.DoString("return 3")[0]) == 3, "a call after Interrupt with nothing running");
            }
            finally
            {
                Dispose(env);
            }
        }

        // LuaOptions.AllowInterrupt (owner, 2026-10-18): true lets Interrupt stop a
        // LuaEnv call without limits; the default (null, off for LuaEnv) leaves such a
        // call alone, so it pays nothing for the entry protocol.
        public static void InterruptWithoutLimits()
        {
            string runtime = Runtime();
            if (runtime == "LuaJIT" || runtime == "Lua 5.3")
            {
                throws<NotSupportedException>(() => new LuaEnv(new LuaOptions { AllowInterrupt = true }), runtime);
                Dispose(new LuaEnv(new LuaOptions { AllowInterrupt = false }));
                return;
            }
            expect(new LuaOptions().AllowInterrupt == null, "AllowInterrupt defaults to null (the API's default)");
            var env = new LuaEnv(new LuaOptions { AllowInterrupt = true });
            try
            {
                expect(env.InstructionLimit == 0 && env.TimeLimit == TimeSpan.Zero, "no limits");
                var other = new System.Threading.Thread(() =>
                {
                    System.Threading.Thread.Sleep(50);
                    env.Interrupt();
                });
                other.Start();
                var e = Stopped<LuaInterruptedException>(env, "while true do end", "Interrupt without limits");
                other.Join();
                expect(e.Limit == LuaLimit.Interrupt, e.Message);
                // Limits set later keep the switch, and removing them again too.
                env.InstructionLimit = 1000000000000L;
                env.InstructionLimit = 0;
                other = new System.Threading.Thread(() =>
                {
                    System.Threading.Thread.Sleep(50);
                    env.Interrupt();
                });
                other.Start();
                Stopped<LuaInterruptedException>(env, "while true do end", "Interrupt after the limits were removed");
                other.Join();
            }
            finally
            {
                Dispose(env);
            }
            // Without the switch an unlimited call is not interruptible: a loop that ends by
            // itself (about 0.2 to 1 s) runs to its end although Interrupt comes after 20 ms.
            foreach (var options in new[] { new LuaOptions(), new LuaOptions { AllowInterrupt = false } })
            {
                env = new LuaEnv(options);
                try
                {
                    var other = new System.Threading.Thread(() =>
                    {
                        System.Threading.Thread.Sleep(20);
                        env.Interrupt();
                    });
                    other.Start();
                    long n = Convert.ToInt64(env.DoString("local n = 0 for i = 1, 3e7 do n = n + 1 end return n")[0]);
                    other.Join();
                    expect(n == 30000000, "AllowInterrupt " + options.AllowInterrupt + ": the call ran to its end");
                }
                finally
                {
                    Dispose(env);
                }
            }
        }

        public static void CBudget()
        {
            if (!HasLimits())
            {
                return;
            }
            var env = new LuaEnv(new LuaOptions { InstructionLimit = 1000000 });
            try
            {
                Stopped<LuaInstructionLimitException>(env, "local s = ('a'):rep(1e5) s:find('.-.-.-.-b')", "a backtracking pattern");
                Stopped<LuaInstructionLimitException>(env, "local s = ('a'):rep(1e6) s:find(('a'):rep(5e5) .. 'b', 1, true)", "a plain find");
                Stopped<LuaInstructionLimitException>(env, "table.move({}, 1, 1 << 62, 2)", "table.move");
                // Normal results are unchanged.
                expect(Convert.ToInt64(env.DoString("return select(2, ('ab'):rep(1000):gsub('a(b)', '%1'))")[0]) == 1000, "gsub count");
            }
            finally
            {
                Dispose(env);
            }
            env = new LuaEnv(new LuaOptions { TimeLimit = TimeSpan.FromMilliseconds(50) });
            try
            {
                Stopped<LuaTimeLimitException>(env, "local s = ('a'):rep(1e5) s:find('.-.-.-.-b')", "a pattern under the time limit alone");
            }
            finally
            {
                Dispose(env);
            }
        }

        static readonly string[] libraryNames = { "coroutine", "string", "table", "math", "utf8", "io", "os", "debug", "package", "bit", "jit" };

        static bool Is(LuaEnv env, string chunk)
        {
            return (bool)env.DoString("return " + chunk)[0];
        }

        static void WithLibraries(LuaLibs libs, Action<LuaEnv> body)
        {
            var env = new LuaEnv(new LuaOptions { Libraries = libs });
            try
            {
                body(env);
            }
            finally
            {
                Dispose(env);
            }
        }

        // LuaOptions.Libraries: the libraries a LuaEnv opens, within what the
        // native library contains (XLUA_LIBS); debug and package keep what the
        // bridge needs.
        public static void Libraries()
        {
            expect(new LuaOptions().Libraries == LuaLibs.Default, "Libraries defaults to Default");
            var built = new System.Collections.Generic.HashSet<string>();
            bool fullDebugByDefault;
            using (var plain = new LuaEnv())
            {
                foreach (var name in libraryNames)
                {
                    if (Is(plain, "type(rawget(_G, '" + name + "')) == 'table'"))
                    {
                        built.Add(name);
                    }
                }
                fullDebugByDefault = Is(plain, "debug.sethook ~= nil");
            }
            bool luajit = built.Contains("jit");
            // Default is new LuaEnv(); All opens everything too (and the whole debug library).
            foreach (var libs in new[] { LuaLibs.Default, LuaLibs.All })
            {
                WithLibraries(libs, env =>
                {
                    foreach (var name in libraryNames)
                    {
                        expect(Is(env, "type(rawget(_G, '" + name + "')) == 'table'") == built.Contains(name), libs + ": " + name);
                    }
                    expect(Is(env, "debug.sethook ~= nil") == (libs == LuaLibs.All || fullDebugByDefault), libs + ": debug.sethook");
                });
            }
            // The safe libraries plus package and debug.
            WithLibraries(LuaLibs.Safe | LuaLibs.Package | LuaLibs.Debug, env =>
            {
                foreach (var name in new[] { "io", "os", "bit", "jit" })
                {
                    expect(Is(env, "rawget(_G, '" + name + "') == nil and package.loaded['" + name + "'] == nil"), "Safe: no " + name);
                }
                expect(Is(env, "not pcall(require, 'os') and not pcall(require, 'io')"), "Safe: require does not find os or io");
                expect(Is(env, "package.preload.ffi == nil"), "Safe: no ffi in package.preload");
                expect(Is(env, "type(utf8) == 'table'") == built.Contains("utf8"), "Safe: utf8 as the build has it");
                expect(Is(env, "('x'):upper() == 'X' and type(coroutine.wrap) == 'function' and math.max(1, 2) == 2"), "Safe: the safe libraries work");
                expect(Is(env, "type(debug.sethook) == 'function'"), "Safe | Debug: the whole debug library");
            });
            // A library the build does not contain stays absent when asked for.
            WithLibraries(LuaLibs.All, env =>
            {
                expect(Is(env, "rawget(_G, 'utf8') == nil") == !built.Contains("utf8"), "All: utf8 only where the build has it");
            });
            // Without Debug: debug.traceback and debug.getinfo, which the error handler and xLua's helpers need.
            WithLibraries(LuaLibs.All & ~LuaLibs.Debug, env =>
            {
                expect(Is(env, @"(function()
                    local names = {}
                    for k in pairs(debug) do names[#names + 1] = k end
                    table.sort(names)
                    return table.concat(names, ',') == 'getinfo,traceback' and package.loaded.debug == debug
                end)()"), "no Debug: debug has traceback and getinfo only");
                var e = throws<LuaException>(() => env.DoString("local function f() error('boom') end f()"), "an error without Debug");
                expect(e.Message.Contains("boom") && e.Message.Contains("stack traceback"), "no Debug: errors keep their traceback: " + e.Message);
                expect(Is(env, "debug.getinfo(1, 'S').what == 'main'"), "no Debug: debug.getinfo");
                // setfenv and getfenv (LuaEnv's emulation on Lua 5.2+) keep working.
                expect(Is(env, "(function() local function f() return x end setfenv(f, {x = 5}) return f() == 5 and getfenv(f).x == 5 end)()"),
                    "no Debug: setfenv and getfenv");
#if !XLUA_NO_UTIL
                expect(Is(env, "type(require('xlua.util').bind) == 'function'"), "no Debug: xlua.util loads");
#endif
            });
            // Without Package: no package table, but require and xLua's loaders work.
            WithLibraries(LuaLibs.All & ~LuaLibs.Package, env =>
            {
                env.AddLoader((ref string path) => path == "libraries_probe" ? System.Text.Encoding.UTF8.GetBytes("return 7") : null);
                expect(Is(env, "rawget(_G, 'package') == nil"), "no Package: no package table");
                expect(Is(env, "require('libraries_probe') == 7 and require('libraries_probe') == 7"), "no Package: require and a custom loader");
                expect(Is(env, "require('string') == string and not pcall(require, 'package')"), "no Package: package.loaded, without package itself");
            });
            // Without String: no string table, and strings have no methods.
            WithLibraries(LuaLibs.All & ~LuaLibs.String, env =>
            {
                expect(Is(env, "rawget(_G, 'string') == nil and getmetatable('') == nil"), "no String: no string library");
                expect(Is(env, "not pcall(function() return ('x'):upper() end)"), "no String: no string methods");
            });
            // Without Coroutine (LuaJIT's base library opens it; it goes too).
            WithLibraries(LuaLibs.All & ~LuaLibs.Coroutine, env =>
            {
                expect(Is(env, "rawget(_G, 'coroutine') == nil and package.loaded.coroutine == nil"), "no Coroutine");
            });
            if (luajit)
            {
                WithLibraries(LuaLibs.All & ~(LuaLibs.Ffi | LuaLibs.Jit | LuaLibs.Bit), env =>
                {
                    expect(Is(env, "jit == nil and bit == nil and package.preload.ffi == nil and not pcall(require, 'ffi')"), "LuaJIT without bit, jit, ffi");
                });
            }
        }
    }
}
